{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "partial",
      "summary_quote": "The bill would create a state-administered Education Freedom Scholarship program for eligible Tennessee residents beginning in the 2025–2026 school year, subject to available funding. Students enrolled in a home school or in a church-related school with which their parent is associated would not qualify.",
      "rationale": "Covers residency and school exclusions, but omits entitlement to attend public school and the specific parent-teacher relationship that limits the church-related-school exclusion."
    },
    {
      "proposition_id": "P2",
      "status": "partial",
      "summary_quote": "enroll the student in a private school to meet compulsory attendance requirements",
      "rationale": "Conveys required private-school enrollment but omits Tennessee location, eligible school categories, and commissioner approval under state board rules."
    },
    {
      "proposition_id": "P3",
      "status": "full",
      "summary_quote": "The bill would create a state-administered Education Freedom Scholarship program for eligible Tennessee residents beginning in the 2025–2026 school year, subject to available funding.",
      "rationale": "Conveys creation, state administration, eligible beneficiaries, the starting school year, and the funding condition; the following discussion describes ongoing operation and program limits."
    },
    {
      "proposition_id": "P4",
      "status": "partial",
      "summary_quote": "For the first year, the state would award up to 20,000 scholarships: 10,000 for students whose household income is no more than 300% of the federal income limit for free or reduced-price lunch, or who meet eligibility definitions cited for existing education programs, and 10,000 for other eligible students, regardless of those criteria. Applications would generally be handled in the order received.",
      "rationale": "Covers the cap, allocation, income threshold, and receipt order, but does not identify the alternative eligibility programs or their statutory definitions and does not specify completed applications."
    },
    {
      "proposition_id": "P5",
      "status": "full",
      "summary_quote": "From 2026–2027 onward, if applications exceed 75% of available scholarships, the department may add up to 5,000 scholarships for the next year; if applications do not exceed 75%, the number must stay the same.",
      "rationale": "Conveys the starting year, threshold, discretionary increase, maximum increase, and mandatory unchanged cap below the threshold. The summary establishes the program's available-funding condition."
    },
    {
      "proposition_id": "P6",
      "status": "partial",
      "summary_quote": "If applications exceed available scholarships, awards would be prioritized for students who received one the year before, then specified lower-income or program-eligible students, students with income up to 300% of the lunch limit, students enrolled or eligible to enroll in public school, and finally other eligible students.",
      "rationale": "Conveys the priority structure but omits the 100% threshold, specific alternative eligibility definitions, and completed-application ordering within tiers. It also broadens kindergarten eligibility to eligibility for public-school enrollment generally."
    },
    {
      "proposition_id": "P7",
      "status": "partial",
      "summary_quote": "To receive a scholarship, a student or parent must apply, enroll the student in a private school to meet compulsory attendance requirements, and not enroll the student in a K–12 public school during a scholarship year.",
      "rationale": "Covers the main participation requirements but omits the expanded definition of parent, the defined public-school categories, and the completed-application requirement."
    },
    {
      "proposition_id": "P8",
      "status": "omitted",
      "summary_quote": "",
      "rationale": "The summary mentions appeals but does not describe authority to award scholarships out of order following an appeal."
    },
    {
      "proposition_id": "P9",
      "status": "full",
      "summary_quote": "A scholarship equals the base funding amount cited in the bill and is solely state-funded.",
      "rationale": "Conveys both the amount formula and exclusive state funding."
    },
    {
      "proposition_id": "P10",
      "status": "full",
      "summary_quote": "Funds must first pay private-school tuition and fees; any remaining funds may pay for specified materials, tutoring, transportation, technology, academic programs, approved postsecondary or credential expenses, and educational therapy. Afterschool childcare is not an allowable expense.",
      "rationale": "Conveys tuition-and-fee priority and limits subsequent spending to specified authorized educational expenses."
    },
    {
      "proposition_id": "P11",
      "status": "partial",
      "summary_quote": "Funds must first pay private-school tuition and fees; any remaining funds may pay for specified materials",
      "rationale": "Conveys materials as an allowable use after tuition and fees, but omits the enumerated items, including uniforms, and the requirement that the private school require them."
    },
    {
      "proposition_id": "P12",
      "status": "partial",
      "summary_quote": "Funds must first pay private-school tuition and fees; any remaining funds may pay for specified materials, tutoring",
      "rationale": "Covers tutoring after tuition and fees but omits the requirement that the tutor or tutoring facility meet department requirements."
    },
    {
      "proposition_id": "P13",
      "status": "partial",
      "summary_quote": "Funds must first pay private-school tuition and fees; any remaining funds may pay for specified materials, tutoring, transportation",
      "rationale": "Covers transportation expenses but omits travel to and from the enrolled private school and use of a qualifying fee-for-service provider."
    },
    {
      "proposition_id": "P14",
      "status": "partial",
      "summary_quote": "Funds must first pay private-school tuition and fees; any remaining funds may pay for specified materials, tutoring, transportation, technology",
      "rationale": "Covers technology spending but omits department requirements and the restriction to the recipient's educational needs."
    },
    {
      "proposition_id": "P15",
      "status": "partial",
      "summary_quote": "Funds must first pay private-school tuition and fees; any remaining funds may pay for specified materials, tutoring, transportation, technology, academic programs, approved postsecondary or credential expenses, and educational therapy. Afterschool childcare is not an allowable expense.",
      "rationale": "Covers academic programs and the childcare exclusion but omits the summer and specialized afterschool scope, covered expense categories, and department requirements."
    },
    {
      "proposition_id": "P16",
      "status": "partial",
      "summary_quote": "Funds must first pay private-school tuition and fees; any remaining funds may pay for specified materials, tutoring, transportation, technology, academic programs, approved postsecondary or credential expenses",
      "rationale": "Conveys approved postsecondary and credential expenses but does not identify early postsecondary courses or examinations, admission examinations, and industry credentials as the authorized fee categories."
    },
    {
      "proposition_id": "P17",
      "status": "partial",
      "summary_quote": "Funds must first pay private-school tuition and fees; any remaining funds may pay for specified materials, tutoring, transportation, technology, academic programs, approved postsecondary or credential expenses, and educational therapy.",
      "rationale": "Covers educational therapy after tuition and fees but omits the requirement that therapists meet department requirements."
    },
    {
      "proposition_id": "P18",
      "status": "full",
      "summary_quote": "Unused funds remain in a student’s account between school years. The account must close and remaining funds return to the state for future scholarships when the student graduates or earns an approved high school equivalency credential, enrolls in public school, completes 13 K–12 school years, withdraws, or is disqualified for not meeting program requirements.",
      "rationale": "Conveys account continuity and rollover subject to specified closure events."
    },
    {
      "proposition_id": "P19",
      "status": "full",
      "summary_quote": "The account must close and remaining funds return to the state for future scholarships when the student graduates or earns an approved high school equivalency credential, enrolls in public school, completes 13 K–12 school years, withdraws, or is disqualified for not meeting program requirements.",
      "rationale": "Conveys mandatory closure, return of funds for future scholarships, and all five triggering events."
    },
    {
      "proposition_id": "P20",
      "status": "full",
      "summary_quote": "Students in grades 3–11 must take an annual nationally standardized test aligned with the private school’s instructional plan or the Tennessee comprehensive assessment test.",
      "rationale": "Conveys the mandatory annual assessment, covered grades, and the two authorized testing alternatives."
    },
    {
      "proposition_id": "P21",
      "status": "partial",
      "summary_quote": "Students in grades 3–11 must take an annual nationally standardized test aligned with the private school’s instructional plan or the Tennessee comprehensive assessment test. Schools must give results to parents",
      "rationale": "Covers annual testing and parental results, but does not expressly place responsibility for administering the assessments on each participating private school."
    },
    {
      "proposition_id": "P22",
      "status": "partial",
      "summary_quote": "Schools must give results to parents and report results annually to the comptroller’s research and education accountability office by June 30; deidentified, grouped data may be used.",
      "rationale": "Covers the reporting recipient, annual deadline, and deidentified reporting option, but omits the 2026 first deadline, required office form, and grade, income, sex, and race analysis requirements."
    },
    {
      "proposition_id": "P23",
      "status": "full",
      "summary_quote": "That office must report annually to legislative education committees.",
      "rationale": "In context, conveys the research and education accountability office's annual assessment-results report to the legislative education committees."
    },
    {
      "proposition_id": "P24",
      "status": "partial",
      "summary_quote": "Private schools accepting scholarship students would remain autonomous",
      "rationale": "Conveys autonomy but omits the distinct legal declaration that participating schools are not state agents."
    },
    {
      "proposition_id": "P25",
      "status": "full",
      "summary_quote": "Private schools accepting scholarship students would remain autonomous and would not have to change their beliefs, practices, admissions, hiring, or curriculum to participate. The program would not expand government authority over them beyond rules narrowly tailored to enforce program requirements.",
      "rationale": "Conveys protection against expanded governmental regulation and all listed areas in which schools need not change to participate."
    },
    {
      "proposition_id": "P26",
      "status": "full",
      "summary_quote": "Students could not receive a scholarship for a school year in which they participate in the state education savings account pilot or individualized education account program.",
      "rationale": "Conveys the same-year prohibition for both named programs."
    },
    {
      "proposition_id": "P27",
      "status": "full",
      "summary_quote": "Scholarship recipients would not retain the right to special education and related services through a public-school individualized education program, but would have the same IDEA rights to equitable services through an individualized service plan as other nonpublic-school students.",
      "rationale": "Conveys the loss of the public-school IEP entitlement and preservation of equitable-service rights on the same basis as other nonpublic-school students."
    },
    {
      "proposition_id": "P28",
      "status": "full",
      "summary_quote": "It cannot be paid directly to the student or parent",
      "rationale": "Expressly conveys the prohibition on direct payment to either recipient or parent."
    },
    {
      "proposition_id": "P29",
      "status": "omitted",
      "summary_quote": "",
      "rationale": "The summary does not state that scholarships are classified as a state or local public benefit."
    },
    {
      "proposition_id": "P30",
      "status": "full",
      "summary_quote": "It cannot be paid directly to the student or parent and would not count as taxable income for them.",
      "rationale": "Conveys the nontaxable-income treatment for both students and parents."
    },
    {
      "proposition_id": "P31",
      "status": "full",
      "summary_quote": "The department must deny an application if the student cannot establish lawful presence in the United States.",
      "rationale": "Conveys the mandatory denial and its lawful-presence condition."
    },
    {
      "proposition_id": "P32",
      "status": "partial",
      "summary_quote": "The rules must provide an appeal process for denied applications.",
      "rationale": "Covers the required appeal process but omits the department's broader implementation rulemaking duty and the Uniform Administrative Procedures Act requirement."
    },
    {
      "proposition_id": "P33",
      "status": "full",
      "summary_quote": "Beginning with 2025–2026, the bill would require additional state funding for a local education agency whose current-year TISA allocation is lower than the prior year’s and whose nonvirtual average daily membership has fallen, so its allocation reaches the prior-year amount.",
      "rationale": "Conveys the start year, both eligibility conditions, the disenrollment measure, and the prior-year funding floor; the next sentence addresses continuing protection."
    },
    {
      "proposition_id": "P34",
      "status": "full",
      "summary_quote": "Beginning in 2026–2027, an agency that has previously received this added funding would, under the stated conditions, receive enough to reach the prior-year allocation plus the added funding it received in that prior year.",
      "rationale": "Conveys the later start year, prior receipt requirement, continuing conditions, and the floor including prior-year supplemental funds."
    },
    {
      "proposition_id": "P35",
      "status": "full",
      "summary_quote": "These funds would be solely state-funded; an agency eligible under this provision would not receive additional funds under the cited alternative provisions.",
      "rationale": "Conveys exclusive state funding and the prohibition on receiving alternative supplemental allocations alongside this protection."
    },
    {
      "proposition_id": "P36",
      "status": "partial",
      "summary_quote": "Subject to appropriation, the department would also award a one-time $2,000 bonus to each teacher employed in a Tennessee K–12 public school for the 2024–2025 school year. The bonus would be state-funded",
      "rationale": "Covers the amount, timing, recipients, funding source, and appropriation condition, but omits the controlling definition of teacher as an existing educator."
    },
    {
      "proposition_id": "P37",
      "status": "full",
      "summary_quote": "The bonus would be state-funded, would not be part of TISA, and would not count as a salary payment or supplement for the cited statutory purpose.",
      "rationale": "Conveys exclusion from TISA and from salary payments or supplements for the specified statutory purpose."
    },
    {
      "proposition_id": "P38",
      "status": "partial",
      "summary_quote": "The bill would direct 80% of the privilege tax covered by the cited provision to an account for local education agencies to construct and maintain public school buildings.",
      "rationale": "Covers the percentage and use, but does not identify the amended privilege-tax provision, the council's distribution duty, or the treasurer's account-administration role."
    },
    {
      "proposition_id": "P39",
      "status": "partial",
      "summary_quote": "In allocating those funds, the state treasurer must consider whether an agency is in an economically distressed or at-risk county, major damage from an emergency or natural disaster, and other demonstrated need.",
      "rationale": "Covers the three general considerations but omits the department's county designation, the requirement that damage affect an existing public school building or facility, and LEA identification of other need."
    },
    {
      "proposition_id": "P40",
      "status": "omitted",
      "summary_quote": "",
      "rationale": "The summary does not mention severability or continued operation of unaffected provisions and applications."
    },
    {
      "proposition_id": "P41",
      "status": "full",
      "summary_quote": "That change would take effect July 1, 2025; the bill’s other sections would take effect upon becoming law.",
      "rationale": "In context, correctly distinguishes the privilege-tax amendment's effective date from the effective date for all other sections."
    }
  ]
}
